const input = require("fs").readFileSync(0, "utf8");
const points = input.trim().split(/\s+/).map(Number);
const n = points.length;

const dp = new Array(n).fill(0);
dp[0] = points[0];
if (n > 1) {
  dp[1] = points[0] + points[1];
}
for (let i = 2; i < n; i++) {
  dp[i] = points[i] + Math.max(dp[i - 1], dp[i - 2]);
}

console.log(`table: ${dp.join(" ")}`);
console.log(`best: ${dp[n - 1]}`);
